{
  "items": [
    {
      "title": "Duisburg Citizen Survey – Spring 2000 (Duisburger Bürgerumfrage Frühjahr 2000)",
      "url_or_doi": "https://doi.org/10.4232/1.3468",
      "justification": "A representative survey of Duisburg residents aged 18–75, conducted in February–March 2000. The dataset is archived by GESIS and covers residents' social and political attitudes, living conditions, and opinions about their city. Particularly relevant for establishing a baseline of social attitudes in Duisburg at the beginning of the 2000s."
    },
    {
      "title": "Duisburg Citizen Survey – Autumn 2000 (Duisburger Bürgerumfrage Herbst 2000)",
      "url_or_doi": "https://doi.org/10.4232/1.3469",
      "justification": "A representative survey of Duisburg residents aged 18–75 conducted in October–November 2000. Archived by GESIS, the dataset includes information relevant to political behaviour, social attitudes, and residents' experiences. Useful for investigating public opinion and comparing attitudes across different survey periods."
    },
    {
      "title": "Duisburg Citizen Survey – Autumn 2004, German Population (Duisburger Bürgerumfrage Herbst 2004)",
      "url_or_doi": "https://doi.org/10.4232/1.4515",
      "justification": "A survey examining the attitudes and living conditions of German residents in Duisburg in 2004. Topics include residential satisfaction, political preferences, voting behaviour, employment, religious participation, trade union membership, and household characteristics. Particularly useful for studying civic engagement, political attitudes, social identity, and socioeconomic differences in Duisburg during the mid-2000s."
    },
    {
      "title": "Duisburg Citizen Survey – Autumn 2005, German Population (Duisburger Bürgerumfrage Herbst 2005)",
      "url_or_doi": "https://doi.org/10.4232/1.4516",
      "justification": "A representative survey examining housing satisfaction, neighbourhood attachment, perceptions of local environmental conditions, political participation, and evaluations of local government. Includes information on voting behaviour in the 2004 municipal elections and 2005 federal elections. Highly relevant for analysing social belonging, civic attitudes, residential satisfaction, and political behaviour in Duisburg."
    },
    {
      "title": "Duisburg Citizen Survey – Autumn 2006, German Population (Duisburger Bürgerumfrage Herbst 2006)",
      "url_or_doi": "https://b2find.eudat.eu/dataset/?tags=economic+situation",
      "justification": "A Duisburg-specific social survey from 2006, indexed in the B2FIND research data catalogue. It examines attitudes toward housing and living conditions, perceptions of economic circumstances in Duisburg and Germany, and opinions about municipal policies. Useful for studying socioeconomic perceptions, satisfaction with urban life, and changes in residents' attitudes during the 2000s. The URL points to a catalogue results page containing the dataset."
    },
    {
      "title": "Duisburg Citizen Survey – Autumn 2001 (Duisburger Bürgerumfrage Herbst 2001)",
      "url_or_doi": "https://access.gesis.org/dbk/35457",
      "justification": "A municipal survey examining Duisburg residents' attitudes toward living in the city. Available documentation includes results on residential attachment, willingness to remain in Duisburg, and differences across age groups, employment categories, educational backgrounds, and political preferences. Particularly valuable for investigating urban identity, residential satisfaction, and social differences in 2001. The linked resource provides survey documentation and aggregated findings."
    },
    {
      "title": "Crime in the Modern City – Longitudinal Study of Youth in Duisburg (Kriminalität in der modernen Stadt)",
      "url_or_doi": "https://search.gesis.org/research_data/ZA8863?lang=de",
      "justification": "A longitudinal criminological and sociological research project examining young people's behaviour and attitudes in Duisburg. The project conducted 13 survey waves between 2002 and 2019, following cohorts initially drawn from Duisburg schools in 2002. Topics include peer-group relationships, leisure activities, social integration, delinquency, victimisation, family relationships, and attitudes toward crime. Especially relevant for understanding youth social behaviour during the 2000s. The linked GESIS record is specifically for the 2013 wave and provides information about the broader longitudinal project; it is not itself a 2000s dataset."
    },
    {
      "title": "German General Social Survey (ALLBUS) – Cumulative Data 1980–2023",
      "url_or_doi": "https://datacatalogue.cessda.eu/detail/974ab6cd948f43d15586822f5f1ecfc7d467587d180e81551a6f5e19fc2e5054?lang=en",
      "justification": "A comprehensive longitudinal collection of repeated cross-sectional surveys measuring social attitudes, values, political participation, interpersonal relationships, religious beliefs, and demographic characteristics in Germany. Includes survey waves from the 2000s. Potentially useful for comparing Duisburg with broader regional and national trends, although it is not Duisburg-specific and identifying Duisburg respondents may require restricted geographical information. Best suited as a complementary dataset."
    },
    {
      "title": "Duisburg Municipal Population Surveys, 1981–2009 (Duisburger Bevölkerungsbefragungen)",
      "url_or_doi": "https://www.duisburg.de/microsites/wahlen/Informationslogistik_Statistik/Bevoelkerungsbefragung/bevoelkerungsbefragung",
      "justification": "The City of Duisburg confirms that it conducted representative population surveys between 1981 and 2009. This municipal survey programme provides an important source for investigating historical changes in residents' attitudes, satisfaction with local living conditions, and perceptions of municipal services. Particularly relevant for locating additional survey results from 2001–2009. The linked page describes the historical survey programme, but does not itself provide all historical microdata."
    }
  ]
}
